-- G1 (case-two plan 3.1, H3): the helper the player named in "Did anyone help?". Nullable: null is "no one helped",
-- and every row written before this migration reads as null. Generated by drizzle-kit from db/schema.ts, then made
-- idempotent by hand (IF NOT EXISTS) like 0000, so a manual apply followed by `npm run db:migrate` is harmless.
-- Apply BEFORE deploying code that has this column in db/schema.ts: Drizzle names every column in its selects and
-- inserts, so new code on an un-migrated table fails accusations closed (503). Old code ignores the column.
ALTER TABLE "closed_games" ADD COLUMN IF NOT EXISTS "accomplice_id" text;
